with filtered_payments as (select * from payments where (status in ('REFUNDED', 'SUCCESS', 'FAILED') and paid_at >= '2025-02-28') or order_id is not null), status_summary as (select status, round(avg(amount), 2) as avg_amount, concat_ws(', ', sort_array(collect_set(status))) as status_values from filtered_payments group by status) select status, avg_amount, status_values from status_summary where avg_amount > 28 order by status_values desc, status limit 20;
